\begin{enumerate}
\item[(a)] The full isometry groups are
\[
\operatorname{Iso}(\mathbb R^n,\overline g)=E(n),\qquad
\operatorname{Iso}(S^n(R),\overline g_R)=O(n+1),\qquad
\operatorname{Iso}(\mathbb H^n(R),\overline g_R)=O^+(n,1).
\]
