\bpnode{prop:exterior-derivative-covariant-formula}
\begin{proposition}
\label{prop:exterior-derivative-covariant-formula}
\dcref{ch5:5-13}

Let $(M,g)$ be a Riemannian manifold.
\begin{enumerate}
\item[(a)] For every $\eta\in\Omega^1(M)$,
\[
d\eta(X,Y)=(\nabla_X\eta)(Y)-(\nabla_Y\eta)(X).
\]
\item[(b)] For every $\eta\in\Omega^k(M)$,
\[
d\eta=(-1)^k(k+1)\operatorname{Alt}(\nabla\eta),
\]
where $\operatorname{Alt}$ is the alternation operator in (B.9).
\end{enumerate}
\end{proposition}

